function FormBuilderJSignatureLauncher(){

    $(".jsignature-container.js-loading").each(function (index, domEle) {
        
        var val = $(domEle).find("input[type='text']");
        var canvas = $(domEle).find(".jsignature");
        var canvas2= $('<div calass="signature-dark-color" style="color: rgb(0, 0, 0);position: absolute;top: 0;left: 0;width: 100%;height: 100%;pointer-events: none;opacity: 0; z-index: -1;">');

        $(domEle).append(canvas2);

        $(domEle).css({
            "position":"relative"
        }).removeClass("js-loading");
       
        function canvasInit(){
            $(canvas).jSignature({
                'background-color': 'transparent',
                'signatureLine': false,
                'decor-color': 'transparent',
                "lineWidth":$(domEle).data("linewidth") || 3,
                "sizeRatio":$(domEle).data("sizeratio") || 4,
                "minFatFingerCompensation": -1
            });
            $(canvas2).jSignature({
                'background-color': 'transparent',
                'signatureLine': false,
                'decor-color': 'transparent',
                "lineWidth":$(domEle).data("linewidth") || 3,
                "sizeRatio":$(domEle).data("sizeratio") || 4,
                "minFatFingerCompensation": -1
            });

            let originalEvent = true;
            $(canvas).on('change', function (e) {
                if($(canvas).jSignature("getData","base30")[1]){
                    $(canvas2).jSignature("setData", "data:" + $(canvas).jSignature("getData","base30").join(",")) 
                    val.val($(canvas2).jSignature("getData"));
                }else{
                    val.val("");
                }
                if(originalEvent){
                    val.trigger("blur");
                }

                if (!($(domEle).find('a.reset').length && $(domEle).find('a.reset').length > 0) ) {
                    $(domEle).prepend("<a class='reset' href='javascript:;' title='Reset' style='position: absolute;right: 5px;top: 5px;background-color: rgba(0,0,0,0.3);width: 24px;height: 24px;border-radius: 50%;color:#FFF'><span style='width: 12px;border-bottom: 2px solid currentColor;position: absolute;left: 50%;top: 50%;margin-left: -6px;transform: rotate(45deg);color:#FFF;'></span><span  style='width: 12px;border-bottom: 2px solid currentColor;position: absolute;left: 50%;top: 50%;margin-left: -6px;transform: rotate(-45deg);color:#FFF;'></span></a>");
                }
            });
            $(domEle).on("click", 'a.reset', function (events) {
                if(events.originalEvent){
                    originalEvent = true;
                }else{
                    originalEvent = false;
                }
                $(canvas).jSignature("reset");
                $(domEle).find("a.reset").remove();
                val.val("");

            });


        }

        if(canvas.is(":hidden")){
           if(typeof MutationObserver =="function"){
                var observer = new MutationObserver(function () {
                    if (canvas.is(":visible")) {
                        observer.disconnect();
                        canvasInit();
                    }
                });
                observer.observe(canvas.parents(":hidden").length ? canvas.parents(":hidden").last()[0] : canvas[0], {
                    "attributes": true
                });
           }else{
                var observer = setInterval(function(){ if (canvas.is(":visible")) {canvasInit(); clearInterval(observer);}},100)
           }
        }else{
            canvasInit();
        }

    });

}

 
